window.SEC_VIDEOS = {"items":[{"id":"OERLpI_jjyI","t":"1 个网关榨干所有 AI 免费额度：Magpie 本地全能中继实测","u":"https://www.youtube.com/watch?v=OERLpI_jjyI","d":"本地 AI 网关实测：一个网关管所有免费额度，用完自动切换。"},{"id":"morMambZqvQ","t":"低成本 eSIM 长期保号实测 + 自动答题脚本白嫖英国流量","u":"https://youtube.com/watch?v=morMambZqvQ","d":"低成本 eSIM 保号 + 免费流量实测，全程免费教程。"}]};

